"""Saved run for Lab 2 (used by Replay when the model cannot be reached)."""
CODE = 'import os\nimport numpy as np\nimport streamlit as st\nfrom openai import AzureOpenAI\nfrom pypdf import PdfReader\n\nAPP_TITLE = "📄 My – Chat with my PDF"\n\n# Connect to Azure AI Foundry using the settings already on this machine\nclient = AzureOpenAI(\n    azure_endpoint=os.environ["FOUNDRY_ENDPOINT"],\n    api_key=os.environ["FOUNDRY_API_KEY"],\n    api_version="2024-10-21",\n)\nCHAT_MODEL = os.environ["MODEL_MINI"]\nEMBED_MODEL = os.environ["MODEL_EMBED"]\nHERE = os.path.dirname(os.path.abspath(__file__))\n\nst.set_page_config(page_title="Chat with my PDF", page_icon="📄", layout="wide")\nst.title(APP_TITLE)\n\n\ndef split_into_chunks(text, size=800, overlap=100):\n    """Cut a page\'s text into overlapping pieces of about `size` characters."""\n    chunks, start = [], 0\n    while start < len(text):\n        chunks.append(text[start:start + size])\n        start += size - overlap\n    return chunks\n\n\ndef embed(texts):\n    """Turn a list of texts into vectors (lists of numbers)."""\n    response = client.embeddings.create(model=EMBED_MODEL, input=texts)\n    return np.array([d.embedding for d in response.data])\n\n\n# ---- Sidebar: upload and index the PDF ----\nwith st.sidebar:\n    pdf = st.file_uploader("Upload a PDF", type="pdf")\n    if pdf and st.session_state.get("file_name") != pdf.name:\n        try:\n            reader = PdfReader(pdf)\n            chunks = []\n            for page_no, page in enumerate(reader.pages, start=1):\n                for piece in split_into_chunks(page.extract_text() or ""):\n                    if piece.strip():\n                        chunks.append({"page": page_no, "text": piece})\n            with st.spinner("Reading and indexing the PDF..."):\n                vectors = embed([c["text"] for c in chunks])\n            st.session_state.update(file_name=pdf.name, chunks=chunks, vectors=vectors,\n                                    pages=len(reader.pages), messages=[])\n        except Exception as e:\n            st.error(f"Could not index the PDF: {e}")\n    if "chunks" in st.session_state:\n        st.success(f"Indexed {len(st.session_state.chunks)} chunks from {st.session_state.pages} pages")\n\ntab_arch, tab_chat = st.tabs(["🏗️ How RAG works", "💬 Chat"])\n\n# ---- Tab 1: the architecture picture ----\nwith tab_arch:\n    image_path = os.path.join(HERE, "rag_architecture.png")\n    if os.path.exists(image_path):\n        st.image(image_path, caption="Reference architecture of a production RAG system")\n    else:\n        st.info("Architecture picture not found (rag_architecture.png).")\n\n# ---- Tab 2: chat on the left, \'under the hood\' on the right ----\nwith tab_chat:\n    left, right = st.columns([3, 1])\n    with right:\n        st.subheader("🔧 Under the hood")\n        vectors = st.session_state.get("vectors")\n        st.markdown(f"**Embedding model:** `{EMBED_MODEL}`")\n        st.markdown(f"**Embedding size:** {vectors.shape[1] if vectors is not None else \'—\'} numbers per chunk")\n        st.markdown("**Vector store:** in-memory NumPy array in `st.session_state` (no vector database)")\n        st.markdown(f"**Vectors stored:** {len(vectors) if vectors is not None else 0}")\n        st.markdown("**Similarity:** cosine · **chunks per question:** 3")\n        st.markdown(f"**Chat model:** `{CHAT_MODEL}`")\n    with left:\n        st.session_state.setdefault("messages", [])\n        chat_box = st.container(height=480)          # messages scroll here; the question box stays below\n        for m in st.session_state.messages:\n            with chat_box.chat_message(m["role"]):\n                st.markdown(m["content"])\n        question = st.chat_input("Ask a question about the PDF")\n        if question:\n            if "chunks" not in st.session_state:\n                st.warning("Please upload a PDF first.")\n            else:\n                st.session_state.messages.append({"role": "user", "content": question})\n                with chat_box.chat_message("user"):\n                    st.markdown(question)\n                try:\n                    # 1. Find the 3 chunks most similar to the question (cosine similarity)\n                    q = embed([question])[0]\n                    v = st.session_state.vectors\n                    scores = v @ q / (np.linalg.norm(v, axis=1) * np.linalg.norm(q))\n                    top = np.argsort(-scores)[:3]\n                    hits = [(st.session_state.chunks[i], float(scores[i])) for i in top]\n                    context = "\\n\\n".join(f"[Page {c[\'page\']}]\\n{c[\'text\']}" for c, _ in hits)\n                    # 2. Ask the model to answer only from those chunks\n                    response = client.chat.completions.create(model=CHAT_MODEL, messages=[\n                        {"role": "system", "content": "Answer only from the context. If the answer is not in the "\n                                                      "context, say: I could not find this in the document. "\n                                                      "Mention the page number."},\n                        {"role": "user", "content": f"Context:\\n{context}\\n\\nQuestion: {question}"},\n                    ])\n                    answer = response.choices[0].message.content\n                    with chat_box.chat_message("assistant"):\n                        st.markdown(answer)\n                        with st.expander("Sources"):\n                            for c, s in hits:\n                                st.markdown(f"**Page {c[\'page\']}** · similarity {s:.2f}")\n                                st.text(c["text"])\n                    st.session_state.messages.append({"role": "assistant", "content": answer})\n                except Exception as e:\n                    st.error(f"Something went wrong: {e}")\n'
